CREATE TABLE "AiControlState" ("agencyId" TEXT NOT NULL,"autoExecutionEnabled" BOOLEAN NOT NULL DEFAULT true,"reason" TEXT,"updatedById" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AiControlState_pkey" PRIMARY KEY ("agencyId"));CREATE TABLE "AiActionAudit" ("id" TEXT NOT NULL,"agencyId" TEXT NOT NULL,"actorId" TEXT,"action" TEXT NOT NULL,"mode" TEXT NOT NULL,"risk" TEXT NOT NULL,"entityType" TEXT,"entityId" TEXT,"status" TEXT NOT NULL,"beforeState" JSONB,"afterState" JSONB,"metadata" JSONB,"error" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "AiActionAudit_pkey" PRIMARY KEY ("id"));CREATE INDEX "AiActionAudit_agencyId_createdAt_idx" ON "AiActionAudit"("agencyId","createdAt");CREATE INDEX "AiActionAudit_action_status_idx" ON "AiActionAudit"("action","status");